fn receive(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut NativeDecodeControl<'_>,RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>)->Result<(),OriginalTurnFailure>{if cx.should_yield()||!crate::registry::fits(cx.retained_grant(),d){return Ok(())}let result=cx.with_native_receiving::<_,NativeConstructionStepFailure<ValueError>>(|native|native.receive_construction_step(d,run));reconcile(cx,result)}
fn native_step<T>(cx:&mut StepContext<'_>,run:impl FnOnce(&mut NativeDecodeControl<'_>)->NativeConstructionStepOutcome<T,OriginalReceivingPrimary>)->Result<(),OriginalTurnFailure>{let result=cx.with_native_receiving::<_,NativeConstructionStepFailure<OriginalReceivingPrimary>>(|native|{let outcome=run(native);let p=outcome.progress;NativeConstructionStepOutcome{result:outcome.result.map(|result|result.map(|_|RetainedCloneStep::Progress(p))),receipt_refusal:outcome.receipt_refusal,progress:p}.into_step_result()});reconcile(cx,result)}
fn reconcile<E:Into<OriginalTurnFailure>>(cx:&mut StepContext<'_>,result:Result<RetainedCloneStep,E>)->Result<(),OriginalTurnFailure>{let result:Result<_,OriginalTurnFailure>=result.map_err(Into::into);let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());let receipt=cx.receiving_issued_grant().map(|grant|cx.consume_receiving_retained(grant,p)).transpose();cx.consume_fuel(p.copied_items as u64);match(result,receipt){(Ok(_),Ok(_))=>Ok(()),(Err(error),Ok(_))=>Err(error.into()),(Ok(_),Err(error))=>Err(error.into()),(Err(error),Err(receipt))=>{let mut error:OriginalTurnFailure=error;error.context_refusal=Some(receipt);Err(error)}}}
fn retire(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut dyn NativeDecodeCloseControl,RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>)->Result<RetainedCloneStep,OriginalTurnFailure>{let grant=cx.retained_grant();if cx.retirement_should_yield()||!crate::registry::fits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let result=cx.with_native_retirement(|native|run(native,grant));let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());let receipt=cx.consume_retained(p);cx.consume_fuel(p.copied_items as u64);match(result,receipt){(Ok(step),Ok(()))=>Ok(step),(Err(error),Ok(()))=>Err(error.into()),(Ok(_),Err(error))=>Err(error.into()),(Err(error),Err(receipt))=>{let mut error=OriginalTurnFailure::from(error);error.receipt_refusal=Some(receipt);Err(error)}}}
fn pair_error(slot:&mut Option<OriginalArtifactPairFailure>,error:OriginalArtifactPairFailure)->ValueError{let progress=error.progress;*slot=Some(error);invalid("original Window Pack/SPR receiving refused; complete cause remains retained").with_retained_progress(progress)}
